import logging
from taf.ul.mobile.ui.android.mobile import Mobile
from taf.ul.mobile.ui.android.exceptions import SlotIndexNotSupported, SelectFailure


class MagicUI311HonorCdyAn900(Mobile):

    def __init__(self, adb_proxy, **kwargs):
        super(MagicUI311HonorCdyAn900, self).__init__(adb_proxy, **kwargs)

    def _tap_sim_card_on_off(self, slot_index):
        logging.debug("return to home desktop")
        self._adb_proxy.input_home_key()
        logging.debug("open ue setting")
        self._adb_proxy.open_setting()
        self._wipe_to_top()
        logging.debug("open mobile network")
        self._tap_menu("Mobile network")
        self._wipe_to_top()
        logging.debug("open mobile network")
        self._tap_menu("SIM management")

        logging.debug("tap sim on off button")
        self._tap_sim_on_off_button(slot_index)

    def _confirm_sim_card_switch(self):
        postion = self._get_switch_sim_card_dialog_comfirm_postion()
        self._adb_proxy.tap_by_postion(postion)

    def _tap_sim_on_off_button(self, slot_index):
        postion = self._get_sim_card_on_off_position(slot_index)
        self._adb_proxy.tap_by_postion(postion)

    @staticmethod
    def _get_sim_card_on_off_position(slot_index):
        if slot_index == 0:
            return (954, 396)
        elif slot_index == 1:
            return (954, 636)
        else:
            raise SlotIndexNotSupported(slot_index)

    @staticmethod
    def _get_switch_sim_card_dialog_comfirm_postion():
        return (768, 2127)

    def switch_network_mode(self, mode_name, *args):
        self._open_setting()
        self._tap_system_updates()
        self._tap_developer_options()
        self._tap_5g_network_mode()
        if self._get_selected_node_title_in_dialog() == mode_name:
            logging.info("has selected specified mode, no action")
        else:
            self._select_5g_network_mode(mode_name)
            self._tap_5g_network_mode()
            selected_node_title = self._get_selected_node_title_in_dialog()
            if selected_node_title != mode_name:
                raise SelectFailure(selected_node_title)
        self._close_setting()

    def switch_apn(self, apn_name):
        self._open_setting()
        self._tap_mobile_network()
        self._tap_mobile_data()
        self._tap_access_point_names()
        if self._get_selected_node_title() == apn_name:
            logging.info("has selected specified apn, no action")
        else:
            self._select_apn(apn_name)
            selected_node_title = self._get_selected_node_title()
            if selected_node_title != apn_name:
                raise SelectFailure(selected_node_title)
        self._close_setting()

    def _tap_system_updates(self):
        self._click_menu("System & updates")

    def _tap_developer_options(self):
        self._click_menu("Developer options")

    def _tap_5g_network_mode(self):
        self._click_menu("5G network mode")

    def _select_5g_network_mode(self, mode_name):
        self._click_menu(mode_name)

    def _tap_mobile_network(self):
        self._click_menu("Mobile network")

    def _tap_mobile_data(self):
        self._click_menu("Mobile data")

    def _tap_access_point_names(self):
        self._click_menu("Access Point Names (APNs)")

    def _select_apn(self, apn_name):
        self._click_menu(apn_name)
